import os

print("--- Starting Forensic Search for Manifest File ---")
target_dir = 'storage/shared/agency_lab/'
search_keywords = ['manifest', 'index', 'files', 'list', 'catalog', 'contents', 'qc_manifest']

potential_files = []

print(f"Searching in: {target_dir}")
for root, dirs, files in os.walk(target_dir):
    for file in files:
        # Check if the filename contains any of the keywords
        if any(keyword in file.lower() for keyword in search_keywords):
            full_path = os.path.join(root, file)
            potential_files.append(full_path)

if potential_files:
    print("\n--- Potential Manifest Files Found ---")
    for f_path in potential_files:
        print(f"- {f_path}")
else:
    print("\n--- No potential manifest files found by filename search. ---")

print("\n--- Forensic Search Complete ---")
